#!/usr/bin/env node
/**
 * Injects signing credentials from android/keystore.properties into the
 * gradle build files generated by `expo prebuild`. Idempotent.
 *
 * Strategy: find the top-level `android { ... }` block in
 * android/app/build.gradle[.kts] and append the signing config + release
 * buildType override just before its closing brace. The patch only applies
 * when android/keystore.properties exists.
 *
 * Usage:
 *   node scripts/patch-android-signing.mjs        # patch if keystore.properties exists
 *   node scripts/patch-android-signing.mjs --undo # remove any prior patch
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = process.cwd();
const CANDIDATES = [
	join(ROOT, "android", "app", "build.gradle"),
	join(ROOT, "android", "app", "build.gradle.kts"),
];

function findGradleFile() {
	for (const p of CANDIDATES) if (existsSync(p)) return p;
	return null;
}

const MARKER = "// >>> rd-manager:release-signing-patch";
const CLOSER = "// <<< rd-manager:release-signing-patch";

const PATCH_GROOVY = `${MARKER}
def keystorePropertiesFile = rootProject.file("keystore.properties")
def keystoreProperties = new Properties()
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}

signingConfigs {
    release {
        if (keystorePropertiesFile.exists()) {
            storeFile file(keystoreProperties["storeFile"])
            storePassword keystoreProperties["storePassword"]
            keyAlias keystoreProperties["keyAlias"]
            keyPassword keystoreProperties["keyPassword"]
        }
    }
}

buildTypes {
    release {
        if (keystorePropertiesFile.exists()) {
            signingConfig signingConfigs.release
        }
    }
}
${CLOSER}
`;

const PATCH_KTS = `${MARKER}
val keystorePropertiesFile = rootProject.file("keystore.properties")
val keystoreProperties = java.util.Properties()
if (keystorePropertiesFile.exists()) {
    java.io.FileInputStream(keystorePropertiesFile).use { keystoreProperties.load(it) }
}

signingConfigs {
    create("release") {
        if (keystorePropertiesFile.exists()) {
            storeFile = file(keystoreProperties["storeFile"] as String)
            storePassword = keystoreProperties["storePassword"] as String
            keyAlias = keystoreProperties["keyAlias"] as String
            keyPassword = keystoreProperties["keyPassword"] as String
        }
    }
}

buildTypes {
    getByName("release") {
        if (keystorePropertiesFile.exists()) {
            signingConfig = signingConfigs.getByName("release")
        }
    }
}
${CLOSER}
`;

/**
 * Find the matching closing brace for the `android {` block by tracking
 * brace depth and skipping over string literals and line/block comments.
 * Returns the index of the closing brace, or -1 if not found.
 */
function findAndroidBlockEnd(source) {
	const openRe = /\bandroid\s*\{/;
	const match = source.match(openRe);
	if (!match || match.index === undefined) return -1;
	let i = match.index + match[0].length - 1; // index of opening '{'
	let depth = 1;
	i++;
	while (i < source.length) {
		const c = source[i];
		const c2 = source[i + 1];
		// Skip line comments
		if (c === "/" && c2 === "/") {
			const eol = source.indexOf("\n", i);
			i = eol === -1 ? source.length : eol + 1;
			continue;
		}
		// Skip block comments
		if (c === "/" && c2 === "*") {
			const end = source.indexOf("*/", i + 2);
			i = end === -1 ? source.length : end + 2;
			continue;
		}
		// Skip single-quoted strings (Groovy/Kotlin)
		if (c === "'" || c === '"') {
			const quote = c;
			i++;
			while (i < source.length && source[i] !== quote) {
				if (source[i] === "\\") i += 2;
				else i++;
			}
			i++; // skip closing quote
			continue;
		}
		if (c === "{") depth++;
		else if (c === "}") {
			depth--;
			if (depth === 0) return i;
		}
		i++;
	}
	return -1;
}

function injectPatch(file, patch) {
	const original = readFileSync(file, "utf8");
	if (original.includes(MARKER)) {
		console.log(`patch-android-signing: already patched (${file}).`);
		return false;
	}
	const end = findAndroidBlockEnd(original);
	if (end === -1) {
		console.error(
			`patch-android-signing: could not find closing brace of \`android { ... }\` in ${file}.`,
		);
		process.exit(1);
	}
	// Insert the patch just before the closing brace, with a leading newline.
	const next =
		original.slice(0, end).replace(/\s+$/, "") +
		"\n\n    " +
		patch.replace(/\n/g, "\n    ") +
		"\n" +
		original.slice(end);
	writeFileSync(file, next, "utf8");
	console.log(
		`patch-android-signing: injected release-signing block into ${file}.`,
	);
	return true;
}

function undo(file) {
	const original = readFileSync(file, "utf8");
	const start = original.indexOf(MARKER);
	const end = original.indexOf(CLOSER);
	if (start === -1 || end === -1) return false;
	// Find the boundaries of the patch line(s): strip from the start of the
	// MARKER's line through the CLOSER's line, plus surrounding blank lines.
	const lineStart = original.lastIndexOf("\n", start);
	const lineEnd = original.indexOf("\n", end + CLOSER.length);
	const cutStart = lineStart === -1 ? 0 : lineStart + 1;
	const cutEnd = lineEnd === -1 ? original.length : lineEnd + 1;
	let next = original.slice(0, cutStart) + original.slice(cutEnd);
	next = next.replace(/\n{3,}/g, "\n\n");
	writeFileSync(file, next, "utf8");
	console.log(`patch-android-signing: removed patch from ${file}.`);
	return true;
}

const isUndo = process.argv.includes("--undo");

if (isUndo) {
	let did = false;
	for (const c of CANDIDATES) {
		if (existsSync(c) && undo(c)) did = true;
	}
	if (!did) console.log("patch-android-signing: nothing to undo.");
	process.exit(0);
}

const gradleFile = findGradleFile();
if (!gradleFile) {
	console.error(
		`patch-android-signing: no gradle file found (${CANDIDATES.join(" or ")}). Run \`npx expo prebuild\` first.`,
	);
	process.exit(1);
}

const patch = gradleFile.endsWith(".kts") ? PATCH_KTS : PATCH_GROOVY;
injectPatch(gradleFile, patch);
